// ScheduleConfig A schedule's settings. Omitted fields take the default. The request
// fields (`url` to `content_type`) work as in `EnqueueRequest`.
type ScheduleConfig struct {
	// BackoffMultiplier Retries back off as for queues (see `QueueConfig`).
	BackoffMultiplier *float64 `json:"backoff_multiplier,omitempty"`

	// Body A raw text body. Use this or `payload`.
	Body *string `json:"body,omitempty"`

	// ContentType Content type of `body`. Defaults to `text/plain; charset=utf-8`.
	ContentType *string `json:"content_type,omitempty"`

	// Cron When to run: five fields (minute, hour, day of month, month, day
	// of week) with `*`, lists, ranges, steps and names (`jan`, `mon`),
	// or `@yearly`, `@monthly`, `@weekly`, `@daily` or `@hourly`. When
	// both day fields are restricted, a day matches either.
	//
	//
	// Example: 0 3 * * *
	Cron string `json:"cron"`

	// Headers Headers sent with every run. `Workly-*` headers are reserved.
	Headers *map[string]string `json:"headers,omitempty"`

	// MaxAttempts Total delivery attempts before a run fails.
	MaxAttempts       *int        `json:"max_attempts,omitempty"`
	MaxBackoffSeconds *float64    `json:"max_backoff_seconds,omitempty"`
	Method            *HTTPMethod `json:"method,omitempty"`
	MinBackoffSeconds *float64    `json:"min_backoff_seconds,omitempty"`

	// Missed What happens to slots missed while the server was down (a slot is
	// missed if it can't fire within a minute). `skip` records the most
	// recent missed slot as a `skipped` run; `catch_up` runs it. Either
	// way, at most one run is created for the missed slots.
	Missed *MissedPolicy `json:"missed,omitempty"`

	// Overlap What happens when a slot comes up while the previous run is still
	// pending or running. `skip` records the slot as a `skipped` run;
	// `allow` runs it alongside.
	Overlap *OverlapPolicy `json:"overlap,omitempty"`

	// Payload A JSON body, sent with `Content-Type: application/json`. Use this or `body`.
	Payload *json.RawMessage `json:"payload,omitempty"`

	// RetryOn4xx Retry 4xx responses. By default only 408 and 429 are retried.
	RetryOn4xx *bool `json:"retry_on_4xx,omitempty"`

	// TimeoutSeconds How long to wait for a response.
	TimeoutSeconds *float64 `json:"timeout_seconds,omitempty"`

	// Timezone IANA timezone the cron expression is read in, e.g.
	// `Europe/Stockholm`. A slot in the hour skipped by a daylight
	// saving change runs right after it; a slot in a repeated hour runs
	// once.
	Timezone *string `json:"timezone,omitempty"`

	// Url The http(s) URL to call.
	//
	// Example: https://api.example.com/reports/nightly
	Url string `json:"url"`
}

